convergences=[
 dict(date="1945-10-19",label="The indictment reaches the cells",eyes=["imt","neave","gilbert","dodd"],note="The court's certificate records only names, dates and places; Neave's later memoir supplies faces and first reactions; Gilbert, arriving the next day, collected the defendants' written comments on the same document; Dodd, the same week, was promoted to run the case it set out."),
 dict(date="1945-11-21",label="Pleas and the opening speech",eyes=["goering","jackson","imt"],note="Göring tried to turn his plea into a speech and was stopped; Jackson was allowed most of a day. The transcript keeps both, the defendant's words and the prosecutor's, in the same record."),
 dict(date="1945-11-29",label="The camp film and Hess's announcement",eyes=["imt","gilbert"],note="The record notes only that a film was shown and authenticated; Gilbert, watching the dock, wrote down who looked away. The next afternoon the transcript caught Hess's own surprise statement."),
 dict(date="1946-01-28",label="The French case and its witnesses",eyes=["imt","vaillant"],note="De Menthon's opening framed the occupation in terms of principle; eleven days later a survivor supplied first-hand testimony, and a defence lawyer tested how she could know what she claimed."),
 dict(date="1946-03-20",label="Göring under cross-examination",eyes=["jackson","goering","dodd","maxwell-fyfe"],note="The transcript shows Jackson struggling; his own deputy Dodd wrote home that he did well; the British deputy, who followed, privately judged Göring very clever and his own approach more effective. The press largely agreed with the British."),
 dict(date="1946-04-15",label="Höss in April",eyes=["hoess","gilbert"],note="Höss's sworn figures entered the record through a defence witness meant to help Kaltenbrunner; in the same week Gilbert interviewed him in his cell and, on 18 April, heard Göring explain how peoples are led to war."),
 dict(date="1946-07-26",label="The closing speeches",eyes=["jackson","shawcross","dodd"],note="Dodd's letter of 16 July shows the closing speech being drafted behind the scenes; Jackson's version answered the defendants' claims of ignorance with documents, while Shawcross, the next day, chose a single eyewitness account."),
 dict(date="1946-10-01",label="Judgment and sentence",eyes=["imt","speer","gilbert","west","dodd"],note="The court's sentences, the convicted men's reactions in the cells, a novelist's view from the press gallery and a prosecutor counting the days until he could sail home all fall on the same two days."),
 dict(date="1946-10-16",label="The night of the executions",eyes=["goering","ksmith","west"],note="Göring's suicide on the evening of 15 October overshadowed the sentence carried out hours later; Smith's wire report gave the world the facts, and West, days later, wondered what Göring's escape from the gallows had done to the meaning of the trial."),
]
